// Normalisasi payload dari Webhook atau Watcher
const body = $input.first().json.body || $input.first().json;

const text = body.content || body.text || '';
const filename = body.filename || body.file_name || 'dokumen_tugas.txt';

if (!text || text.trim().length === 0) {
  throw new Error('Payload harus memuat teks tugas dalam field content atau text.');
}

return [{
  json: {
    raw_text: text.slice(0, 10000),
    filename: filename,
    received_at: new Date().toISOString()
  }
}];

