// Parse hasil LLM dan bangun iCalendar (.ics) + Google Calendar Link
const aiResponse = $input.first().json;
let rawContent = '';

if (aiResponse.choices && aiResponse.choices.length > 0) {
  rawContent = aiResponse.choices[0].message.content;
} else {
  throw new Error('Gagal menerima respons AI dari 9Router.');
}

// Bersihkan markdown fence ```json jika ada
let cleaned = rawContent.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let task = {};
try {
  task = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    task = JSON.parse(match[0]);
  } else {
    throw new Error('Respons AI tidak memuat format JSON yang valid.');
  }
}

const course = task.course || 'Perkuliahan';
const title = task.title || 'Tugas Baru';
const deadline = task.deadline || '';
const priority = (task.priority || 'MEDIUM').toUpperCase();
const summary = task.summary || 'Instruksi pengerjaan tugas akademik.';

// Bangun URL 1-Click Google Calendar
let gcalUrl = '';
if (deadline) {
  const cleanDate = deadline.replace(/[^0-9]/g, '');
  const startFmt = cleanDate.padEnd(14, '0').slice(0, 8) + 'T' + cleanDate.padEnd(14, '0').slice(8, 14) + 'Z';
  const titleEnc = encodeURIComponent(`[${course}] ${title}`.slice(0, 70));
  const descEnc = encodeURIComponent(summary.slice(0, 120));
  gcalUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${titleEnc}&dates=${startFmt}/${startFmt}&details=${descEnc}&location=Online+%2F+LMS`;
}

// Format checklist subtask
const subtaskList = (task.subtasks || []).map(st => `▫️ ${st}`).join('\n');

// Pilih warna embed Discord berdasarkan prioritas
let colorInt = 5793266; // Blue default
if (priority === 'HIGH') colorInt = 15548997; // Red
else if (priority === 'MEDIUM') colorInt = 16705372; // Amber
else if (priority === 'LOW') colorInt = 5763719; // Green

return [{
  json: {
    task: task,
    course: course,
    title: title,
    deadline: deadline,
    priority: priority,
    summary: summary,
    subtasks_formatted: subtaskList,
    google_calendar_url: gcalUrl,
    color_int: colorInt
  }
}];

